def monitor(rows,out,g,keep_history,competitor_first,need_dif):
 pending=None;withdrawals=[];closed={};created={}
 def close(reason,time):
  nonlocal pending
  if pending:closed[pending['anchor']]=dict(reason=reason,time=time)
  pending=None
 for i,r in enumerate(rows):
  z=out[i];topnew=z['event_direction']==1 and z['event'] in ('DULL','STRUCTURE');flip=i>0 and (rows[i-1]['hist']>0)!=(r['hist']>0)
  # Raw reference cross precedes any historical diagnostic; ordinary topCANCEL stays separate.
  if pending and r['dif']>pending['old_ref']:close('original_reference_break',r['time'])
  if not keep_history and flip:close('drop_history_on_hist_sign_change',r['time'])
  if topnew and competitor_first:close('new_top_'+z['event'],r['time'])
  if pending and r['time']>pending['anchor']:
   flags,nums=rule(r,rows[i-1],pending['peak']['close'],g)
   if flags['price_and_dif' if need_dif else 'price_only']:
    withdrawals.append(dict(anchor=pending['anchor'],time=r['time'],kind='RESEARCH_HISTORICAL_WITHDRAWAL',baseline_event=z['event'],baseline_state=z['state'],**{k:v for k,v in nums.items() if k!='time'}));close('diagnostic_withdrawal',r['time'])
  if topnew and not competitor_first:close('new_top_'+z['event'],r['time'])
  if z['event']=='STRUCTURE' and z['event_direction']==1:
   end=i if r['hist']>0 else i-1;start=end
   while start>0 and rows[start-1]['hist']>0:start-=1
   peak=max(rows[start:end+1],key=lambda q:q['close'])
   pending=dict(anchor=r['time'],old_ref=z['event_ref_dif'],peak=dict(peak));created[r['time']]=dict(pending)
   # Negative-bar confirmation and current-wave reset can occur on the same bar.
   if not keep_history and r['hist']<=0:close('drop_history_on_confirmation_color_flip',r['time'])
 return dict(withdrawals=withdrawals,closed=closed,created=created)
